+    flex: 1;
+    overflow-y: auto;
+    padding: 0.75rem 1rem;
+}
+
+.thread-reply {
+    padding: 0.4rem 0;
+    border-bottom: 1px solid #3b3f47;
+}
+
+.thread-reply:last-child {
+    border-bottom: none;
+}
+
+/* Layout with/without thread panel */
+.chat-layout:not(.thread-open) .message-area {
+    width: 80%;
+}
+
+.chat-layout.thread-open .message-area {
+    width: 55%;
+}
+

